CREATE TABLE enterprise_suppliers (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, tenant_id UUID REFERENCES organizations(id) ON DELETE CASCADE, supplier_name TEXT NOT NULL, category TEXT NOT NULL, criticality TEXT DEFAULT 'BUSINESS_CRITICAL', status TEXT DEFAULT 'ACTIVE', geographic_region TEXT DEFAULT 'GLOBAL', annual_spend_usd NUMERIC(14,2) DEFAULT 1200000.00, provenance_hash TEXT NOT NULL, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE enterprise_vendors (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, vendor_name TEXT NOT NULL, vendor_type TEXT DEFAULT 'TECHNOLOGY_PROVIDER', criticality TEXT DEFAULT 'BUSINESS_CRITICAL', switching_cost_usd NUMERIC(14,2) DEFAULT 350000.00, status TEXT DEFAULT 'ACTIVE', created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE enterprise_supplier_performance (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, supplier_id UUID REFERENCES enterprise_suppliers(id) ON DELETE CASCADE, on_time_delivery_rate NUMERIC(5,2) DEFAULT 97.2, fulfillment_rate NUMERIC(5,2) DEFAULT 98.5, defect_rate NUMERIC(5,2) DEFAULT 0.3, sla_compliance_rate NUMERIC(5,2) DEFAULT 99.1, evaluated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE enterprise_supplier_risks (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, supplier_id UUID REFERENCES enterprise_suppliers(id) ON DELETE CASCADE, risk_type TEXT NOT NULL, risk_level TEXT DEFAULT 'MEDIUM', concentration_risk TEXT DEFAULT 'SINGLE_SOURCE', confidence_score NUMERIC(5,2) DEFAULT 82.0, provenance_hash TEXT NOT NULL, assessed_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE enterprise_supplier_concentration (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, supplier_id UUID REFERENCES enterprise_suppliers(id) ON DELETE CASCADE, concentration_type TEXT DEFAULT 'SPEND_CONCENTRATION', concentration_percentage NUMERIC(5,2) DEFAULT 68.0, is_single_source BOOLEAN DEFAULT false, detected_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE enterprise_procurement_spend (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, supplier_id UUID REFERENCES enterprise_suppliers(id) ON DELETE CASCADE, spend_category TEXT NOT NULL, total_spend_usd NUMERIC(14,2) NOT NULL, period TEXT DEFAULT 'Q4_2025', unit_price NUMERIC(10,4) DEFAULT 0.0, price_variance_pct NUMERIC(5,2) DEFAULT 0.0, recorded_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE enterprise_procurement_performance (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, cycle_time_days NUMERIC(6,2) DEFAULT 12.5, order_to_delivery_days NUMERIC(6,2) DEFAULT 18.3, po_accuracy_rate NUMERIC(5,2) DEFAULT 99.2, fulfillment_reliability_rate NUMERIC(5,2) DEFAULT 98.7, evaluated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE enterprise_procurement_leakage (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, leakage_type TEXT NOT NULL, estimated_leakage_usd NUMERIC(14,2) DEFAULT 45000.00, status TEXT DEFAULT 'ANOMALY_DETECTED', confidence_score NUMERIC(5,2) DEFAULT 75.0, detected_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE enterprise_supplier_contracts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, supplier_id UUID REFERENCES enterprise_suppliers(id) ON DELETE CASCADE, contract_name TEXT NOT NULL, effective_date DATE NOT NULL, expiration_date DATE NOT NULL, annual_value_usd NUMERIC(14,2) DEFAULT 500000.00, minimum_commitment_usd NUMERIC(14,2) DEFAULT 100000.00, auto_renewal BOOLEAN DEFAULT true, status TEXT DEFAULT 'ACTIVE', provenance_hash TEXT NOT NULL, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE enterprise_supply_chain_dependencies (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, upstream_entity TEXT NOT NULL, downstream_entity TEXT NOT NULL, dependency_type TEXT DEFAULT 'DIRECT', criticality TEXT DEFAULT 'HIGH', lead_time_days INTEGER DEFAULT 14, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE enterprise_supply_chain_blast_radius (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, trigger_supplier_id UUID REFERENCES enterprise_suppliers(id) ON DELETE CASCADE, affected_systems JSONB DEFAULT '[]'::jsonb, affected_revenue_usd NUMERIC(14,2) DEFAULT 0.00, blast_radius_score NUMERIC(5,2) DEFAULT 0.00, status TEXT DEFAULT 'SIMULATED', evaluated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE enterprise_supplier_substitution (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, incumbent_supplier_id UUID REFERENCES enterprise_suppliers(id) ON DELETE CASCADE, alternate_supplier_name TEXT NOT NULL, switching_cost_usd NUMERIC(14,2) DEFAULT 150000.00, estimated_payback_months INTEGER DEFAULT 12, feasibility_score NUMERIC(5,2) DEFAULT 78.0, status TEXT DEFAULT 'AI_PROPOSED', evaluated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE enterprise_sourcing_strategies (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, strategy_type TEXT DEFAULT 'DUAL_SOURCE', target_category TEXT NOT NULL, rationale TEXT NOT NULL, expected_risk_reduction_pct NUMERIC(5,2) DEFAULT 35.0, status TEXT DEFAULT 'AI_PROPOSED', created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE enterprise_supplier_scenarios (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, scenario_name TEXT NOT NULL, scenario_type TEXT DEFAULT 'SUPPLIER_FAILURE', simulated_impact_usd NUMERIC(14,2) DEFAULT 850000.00, recovery_time_days INTEGER DEFAULT 45, status TEXT DEFAULT 'SIMULATED', created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE enterprise_supply_chain_forecasts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, forecast_horizon TEXT DEFAULT '12_MONTHS', projected_spend_usd NUMERIC(14,2) DEFAULT 4200000.00, projected_lead_time_days NUMERIC(6,2) DEFAULT 16.5, status TEXT DEFAULT 'FORECAST', confidence_score NUMERIC(5,2) DEFAULT 82.0, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE enterprise_supplier_resilience (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, supplier_id UUID REFERENCES enterprise_suppliers(id) ON DELETE CASCADE, recovery_time_hours NUMERIC(8,2) DEFAULT 72.0, has_backup_supplier BOOLEAN DEFAULT false, geographic_redundancy TEXT DEFAULT 'SINGLE_REGION', resilience_score NUMERIC(5,2) DEFAULT 68.0, evaluated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE enterprise_ecosystem_intelligence (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, entity_name TEXT NOT NULL, entity_role TEXT DEFAULT 'STRATEGIC_PARTNER', dependency_level TEXT DEFAULT 'MODERATE', ecosystem_concentration_score NUMERIC(5,2) DEFAULT 55.0, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE enterprise_procurement_opportunities (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, opportunity_type TEXT DEFAULT 'COST_REDUCTION', estimated_savings_usd NUMERIC(14,2) DEFAULT 280000.00, feasibility_score NUMERIC(5,2) DEFAULT 84.0, status TEXT DEFAULT 'AI_PROPOSED', created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE enterprise_supplier_negotiation (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, supplier_id UUID REFERENCES enterprise_suppliers(id) ON DELETE CASCADE, buyer_leverage_score NUMERIC(5,2) DEFAULT 62.0, supplier_leverage_score NUMERIC(5,2) DEFAULT 55.0, estimated_savings_potential_usd NUMERIC(14,2) DEFAULT 180000.00, status TEXT DEFAULT 'AI_PROPOSED', evaluated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE enterprise_procurement_value (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, projected_savings_usd NUMERIC(14,2) NOT NULL, realized_savings_usd NUMERIC(14,2) DEFAULT 0.00, variance_usd NUMERIC(14,2) DEFAULT 0.00, status TEXT DEFAULT 'OBSERVED', recorded_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE enterprise_procurement_drift (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, entity_id UUID NOT NULL, drift_type TEXT NOT NULL, drift_level TEXT DEFAULT 'NO_DRIFT', detected_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE enterprise_procurement_learning (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, event_type TEXT NOT NULL, description TEXT NOT NULL, append_only BOOLEAN DEFAULT true, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE enterprise_procurement_recommendations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, recommendation_type TEXT NOT NULL, title TEXT NOT NULL, rationale TEXT NOT NULL, confidence_score NUMERIC(5,2) DEFAULT 85.0, status TEXT DEFAULT 'AI_PROPOSED', created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE enterprise_procurement_traces (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE, root_signal_id TEXT NOT NULL, trace_payload JSONB DEFAULT '{}'::jsonb, provenance_hash TEXT NOT NULL, generated_at TIMESTAMPTZ DEFAULT NOW());

ALTER TABLE enterprise_suppliers ENABLE ROW LEVEL SECURITY;
ALTER TABLE enterprise_vendors ENABLE ROW LEVEL SECURITY;
